import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split("\\s+");
        int n = Integer.parseInt(input[0]);
        int mod = Integer.parseInt(input[1]);
        List<Integer> mem = new ArrayList<>();
        mem.add(0);
        mem.add(1);
        int total = 1;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            int current_sum = total;

            for (int f = 2; f < limit; f++) {
                current_sum = (current_sum + mem.get(i / f)) % mod;
            }

            int b = i;
            for (int j = 1; j <= i / limit; j++) {
                int nxt = i / (j + 1);
                current_sum = (current_sum + (b - nxt) * (long) mem.get(j) % mod) % mod;
                b = nxt;
            }

            total = (total + current_sum) % mod;
            mem.add(current_sum);
        }

        System.out.println(mem.get(mem.size() - 1));
    }
}
